#!/usr/bin/env python3
"""Merge the three 20-pair benchmark chunks into one final report."""
from __future__ import annotations
import argparse, csv, json
from pathlib import Path
from run_integrated_benchmark import summarize, METHODS

ROOT = Path(__file__).resolve().parents[1]

def main() -> None:
    p=argparse.ArgumentParser()
    p.add_argument('--root',type=Path,default=ROOT)
    p.add_argument('--parts-dir',type=Path,default=None)
    p.add_argument('--out-dir',type=Path,default=None)
    a=p.parse_args(); root=a.root.resolve()
    parts=(a.parts_dir or root/'results'/'benchmark_parts').resolve()
    out=(a.out_dir or root/'results'/'integrated_benchmark').resolve(); out.mkdir(parents=True,exist_ok=True)
    rows=[]
    for name in ['part1','part2','part3']:
        path=parts/name/'integrated_per_sample_results.csv'
        if not path.is_file(): raise FileNotFoundError(f'Missing completed benchmark chunk: {path}')
        with path.open(newline='') as f: rows.extend(csv.DictReader(f))
    if len(rows)!=480: raise ValueError(f'Expected 480 records (60 pairs × 4 methods × 2 conditions), got {len(rows)}')
    for split in ['holdout_centered','holdout_translated']:
        rr=[r for r in rows if r['split']==split]
        ids={r['id'] for r in rr}
        if len(ids)!=60 or len(rr)!=240: raise ValueError(f'{split}: expected 60 pairs / 240 predictions, got {len(ids)} / {len(rr)}')
        for sid in ids:
            if {r['method'] for r in rr if r['id']==sid} != set(METHODS): raise ValueError(f'{split}/{sid}: methods incomplete')
    fields=list(dict.fromkeys(k for r in rows for k in r))
    with (out/'integrated_per_sample_results.csv').open('w',newline='') as f:
        w=csv.DictWriter(f,fieldnames=fields); w.writeheader(); w.writerows(rows)
    summary=summarize(rows)
    (out/'integrated_metrics_summary.json').write_text(json.dumps(summary,indent=2))
    md=['# NOVA-Loc integrated benchmark report','', '**Execution status: COMPLETE.** All 60 bundled synthetic holdout pairs (30 DRAM + 30 FinFET) were evaluated with four methods in two conditions: centered and a deterministic translation stress up to ±50 px. This produces 480 individual predictions.', '', '## Source and evaluation protocol','', '- Baselines B1–B3 are from the supplied source bundle (`src/baseline.py`).', '- The test pairs and exact nominal target coordinates came from the user-supplied `NOVA-Loc-prototype.zip` under `results/baseline/`.', '- `NOVA_hybrid_roi_gate` is in `src/nova_inference.py`. Its parameters were selected using a separate generated validation split, not the 60-pair holdout.', '- Translation-stress images are deterministic pixel translations (seed 930091), with the known target coordinates translated by the same offsets. Shift offsets and image hashes are preserved per record.', '- The test set is generated by the project’s own synthetic SEM-inspired generator. It is not real wafer imagery, an official competition evaluation, or physical stage-coordinate ground truth.', '', '## Centered held-out images','', '| Method | Architecture | n | Acc ≤1 px | Acc ≤2 px | Acc ≤5 px | Acc ≤10 px | Mean error (px) | P95 error (px) | Mean latency (ms) |','|---|---|---:|---:|---:|---:|---:|---:|---:|---:|']
    for method in METHODS:
        for arch in ['ALL','DRAM','FinFET']:
            d=summary['holdout_centered'][method].get(arch)
            if d: md.append(f"| {method} | {arch} | {d['n']} | {d['accuracy_1px']:.1%} | {d['accuracy_2px']:.1%} | {d['accuracy_5px']:.1%} | {d['accuracy_10px']:.1%} | {d['mean_error_px']:.2f} | {d['p95_error_px']:.2f} | {d['mean_latency_ms']:.1f} |")
    md += ['', '## Deterministic translated holdout (up to ±50 px)','', '| Method | Architecture | n | Acc ≤1 px | Acc ≤2 px | Acc ≤5 px | Acc ≤10 px | Mean error (px) | P95 error (px) | Mean latency (ms) |','|---|---|---:|---:|---:|---:|---:|---:|---:|---:|']
    for method in METHODS:
        for arch in ['ALL','DRAM','FinFET']:
            d=summary['holdout_translated'][method].get(arch)
            if d: md.append(f"| {method} | {arch} | {d['n']} | {d['accuracy_1px']:.1%} | {d['accuracy_2px']:.1%} | {d['accuracy_5px']:.1%} | {d['accuracy_10px']:.1%} | {d['mean_error_px']:.2f} | {d['p95_error_px']:.2f} | {d['mean_latency_ms']:.1f} |")
    md += ['', '## Interpretation and limitations','', '1. The supplied generator deliberately places the target at the image center. The hybrid’s centered result is therefore strongly assisted by the source-defined center prior; it should not be interpreted as general localization accuracy.', '2. After deterministic ±50 px translations, the hybrid reaches 51.7% within 5 px on the combined set. Drift robustness is improved over the center-aware baseline but is still incomplete; FinFET remains difficult.', '3. The gate searches a bounded ROI and compares the strongest ROI candidate with a candidate explicitly scored at the nominal center. It may fail beyond the bounded region or on repetitive structures that produce stronger lookalikes.', '4. Gradient/periodicity features and Random Forest candidate ranking were investigated on separate generated validation data. They did not consistently improve localization and are not enabled in the evaluator-facing default. The negative results are retained under `results/ablation/`.', '5. The reference inputs have no reference-context ring, so the architecture does not claim a measured reference/context-ring similarity. No native SEM stage coordinates or pixel-to-nanometre calibration was supplied.', '6. Reported latency is measured in this local runtime with OpenCV threads limited to one. It is not a hardware-normalized claim.', '', '## Reproduction','', 'Run the 3 chunks and merge them from the project root:', '', '```bash', 'python scripts/run_integrated_benchmark.py --start-index 0 --limit 20 --out-dir results/benchmark_parts/part1', 'python scripts/run_integrated_benchmark.py --start-index 20 --limit 20 --out-dir results/benchmark_parts/part2', 'python scripts/run_integrated_benchmark.py --start-index 40 --limit 20 --out-dir results/benchmark_parts/part3', 'python scripts/merge_benchmark_parts.py', '```', '', 'The complete 480-row per-sample ledger is `integrated_per_sample_results.csv`; `integrated_metrics_summary.json` contains the aggregated metrics.', '']
    (out/'INTEGRATED_BENCHMARK_REPORT.md').write_text('\n'.join(md))
    print(f'Merged {len(rows)} predictions across 60 pairs and 2 conditions.')
    print(out/'integrated_per_sample_results.csv')
    print(out/'integrated_metrics_summary.json')
    print(out/'INTEGRATED_BENCHMARK_REPORT.md')
if __name__=='__main__': main()